  put('s_m2', 5, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="炭酸水素ナトリウムとうすい塩酸の反応。ふたをしないと二酸化炭素が出ていき、はかった質量は減る。密閉すると質量は変わらない"><path d="M16 50 L16 110 L68 110 L68 50" class="ax"/><rect x="17" y="78" width="50" height="31" class="fl"/><circle cx="30" cy="70" r="3" class="ax"/><circle cx="42" cy="62" r="3" class="ax"/><circle cx="54" cy="70" r="3" class="ax"/><line x1="34" y1="46" x2="26" y2="26" class="cv2"/><path d="M29.1 28.5 L26 26 L25.5 30" class="cv2"/><line x1="50" y1="46" x2="58" y2="26" class="cv2"/><path d="M58.5 30 L58 26 L54.9 28.5" class="cv2"/><text x="46" y="18" text-anchor="middle">CO₂ が出ていく</text><rect x="8" y="112" width="68" height="8" class="bx"/><text x="42" y="134" text-anchor="middle">ふたなし</text><text x="42" y="148" text-anchor="middle">質量が減る</text><path d="M152 110 L152 60 L164 48 L164 36 L180 36 L180 48 L192 60 L192 110 Z" class="ax"/><rect x="153" y="78" width="38" height="31" class="fl"/><rect x="161" y="30" width="22" height="7" class="tr"/><circle cx="164" cy="68" r="3" class="ax"/><circle cx="178" cy="60" r="3" class="ax"/><circle cx="172" cy="72" r="3" class="ax"/><text x="172" y="22" text-anchor="middle">ふた</text><rect x="138" y="112" width="68" height="8" class="bx"/><text x="168" y="134" text-anchor="middle">密閉</text><text x="168" y="148" text-anchor="middle">質量は変わらない</text><text x="110" y="70" text-anchor="middle">炭酸水素</text><text x="110" y="84" text-anchor="middle">ナトリウム</text><text x="110" y="98" text-anchor="middle">+塩酸</text></svg>');
  put('s_m2', 9, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="酸素との結びつきやすさはマグネシウム>炭素・水素>銅。酸素は結びつきやすい相手のほうへ移るので、炭素は酸化銅を還元できるが、酸化マグネシウムは還元できない"><line x1="205" y1="30" x2="15" y2="30" class="cv2"/><path d="M19.4 27.6 L15 30 L19.4 32.4" class="cv2"/><text x="110" y="20" text-anchor="middle">酸素と結びつきやすい</text><rect x="20" y="40" width="46" height="24" rx="4" class="tr"/><text x="43" y="56" text-anchor="middle">Mg</text><rect x="88" y="40" width="46" height="24" rx="4" class="tr"/><text x="111" y="56" text-anchor="middle">C・H₂</text><rect x="156" y="40" width="46" height="24" rx="4" class="tr"/><text x="179" y="56" text-anchor="middle">Cu</text><path d="M179 66 Q145 92 115 70" class="cv"/><path d="M119.8 71.2 L115 70 L116.6 74.7" class="cv"/><path d="M111 66 Q77 92 47 70" class="cv"/><path d="M51.8 71.2 L47 70 L48.6 74.7" class="cv"/><text x="145" y="92" text-anchor="middle">O が移る</text><text x="77" y="92" text-anchor="middle">O が移る</text><text x="8" y="112">2CuO + C → 2Cu + CO₂ ○</text><text x="8" y="128">2Mg + CO₂ → 2MgO + C ○</text><text x="8" y="144">MgO + C → 反応しない ×</text></svg>');
