  put('s_ion', 4, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="ダニエル電池。亜鉛板では亜鉛が電子を出して亜鉛イオンになりとけ出し(−極)、電子は導線を通って銅板へ流れ、銅イオンが受け取って銅になる(+極)。電流は電子と逆向き"><path d="M25 55 L25 122 L195 122 L195 55" class="ax"/><rect x="26" y="66" width="168" height="55" class="fl"/><line x1="110" y1="58" x2="110" y2="122" class="dash"/><rect x="52" y="45" width="8" height="65" class="bx"/><rect x="160" y="45" width="8" height="65" class="bx"/><line x1="56" y1="45" x2="56" y2="22" class="ax"/><line x1="56" y1="22" x2="104" y2="22" class="ax"/><circle cx="110" cy="22" r="6" class="bx"/><line x1="116" y1="22" x2="164" y2="22" class="ax"/><line x1="164" y1="22" x2="164" y2="45" class="ax"/><line x1="66" y1="12" x2="96" y2="12" class="cv"/><path d="M91.6 14.4 L96 12 L91.6 9.6" class="cv"/><text x="100" y="15">電子 e⁻</text><line x1="150" y1="34" x2="124" y2="34" class="cv2"/><path d="M127.5 32.1 L124 34 L127.5 35.9" class="cv2"/><text x="126" y="46">電流</text><text x="4" y="52">−極</text><text x="4" y="66">Zn</text><text x="173" y="40">+極</text><text x="173" y="54">Cu</text><text x="66" y="84">Zn²⁺</text><line x1="62" y1="92" x2="82" y2="98" class="cv2"/><path d="M78.1 98.8 L82 98 L79.2 95.2" class="cv2"/><text x="122" y="84">Cu²⁺</text><line x1="140" y1="92" x2="156" y2="98" class="cv2"/><path d="M152 98.6 L156 98 L153.4 95" class="cv2"/><text x="30" y="116">ZnSO₄</text><text x="150" y="116">CuSO₄</text><text x="110" y="134" text-anchor="middle">セロハン</text><text x="4" y="148">Zn→Zn²⁺+2e⁻</text><text x="216" y="148" text-anchor="end">Cu²⁺+2e⁻→Cu</text></svg>');
