  put('s_m4', 4, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="飽和水蒸気量の曲線。気温25℃で1m³に12.8gの水蒸気をふくむ空気は、湿度が12.8÷23.1×100≒55%。冷やすと15℃で飽和し、ここが露点"><line x1="30" y1="130" x2="212" y2="130" class="ax"/><line x1="30" y1="130" x2="30" y2="14" class="ax"/><path d="M30 117 L54.5 111.6 L79 104.6 L103.5 95.4 L128 83.3 L152.5 67.6 L177 47.9 L201.5 23.1" class="cv"/><circle cx="152.5" cy="95.4" r="3" class="pt"/><circle cx="103.5" cy="95.4" r="3" class="pt"/><line x1="148.5" y1="95.4" x2="108.5" y2="95.4" class="cv2"/><path d="M112 93.5 L108.5 95.4 L112 97.4" class="cv2"/><line x1="152.5" y1="95.4" x2="152.5" y2="67.6" class="dash"/><line x1="103.5" y1="95.4" x2="103.5" y2="130" class="dash"/><line x1="152.5" y1="95.4" x2="152.5" y2="130" class="dash"/><text x="103.5" y="143" text-anchor="middle">15</text><text x="152.5" y="143" text-anchor="middle">25</text><text x="30" y="143" text-anchor="middle">0</text><text x="201.5" y="143" text-anchor="middle">35</text><text x="34" y="12">水蒸気量[g/m³]</text><text x="212" y="122" text-anchor="end">気温[℃]</text><text x="156.5" y="99.4">12.8g</text><text x="158" y="80">飽和 23.1g</text><text x="36" y="81.4">露点 15℃</text><text x="118" y="30">飽和水蒸気量</text><text x="36" y="40">湿度=12.8÷23.1×100</text><text x="36" y="54">≒ 55%</text></svg>');
  put('s_m4', 9, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="フェーン現象。気温20℃・露点12℃の空気が山をのぼると800mで12℃になり雲ができ、雲の中では100mにつき0.5℃ずつ下がって山頂2000mで6℃。下りは1℃ずつ上がり、ふもとで26℃の乾いた風になる"><path d="M10 135 L110 35 L210 135 Z" class="tr"/><circle cx="44" cy="82" r="12" class="bx"/><circle cx="60" cy="68" r="13" class="bx"/><circle cx="76" cy="54" r="12" class="bx"/><circle cx="92" cy="44" r="10" class="bx"/><circle cx="60" cy="88" r="9" class="bx"/><line x1="10" y1="95" x2="60" y2="95" class="dash"/><line x1="40" y1="104" x2="37" y2="112" class="cv"/><line x1="50" y1="100" x2="47" y2="108" class="cv"/><line x1="30" y1="108" x2="27" y2="116" class="cv"/><line x1="150" y1="70" x2="182" y2="102" class="cv2"/><path d="M177.2 100.6 L182 102 L180.6 97.2" class="cv2"/><text x="4" y="148">20℃</text><text x="2" y="92">12℃</text><text x="110" y="26" text-anchor="middle">6℃(2000m)</text><text x="178" y="148">26℃</text><text x="168" y="66">乾いた風</text><text x="118" y="148">高温で乾く</text><text x="56" y="130">−1℃</text><text x="70" y="108">雲:−0.5℃</text><text x="130" y="128">+1℃</text><text x="4" y="14">温度変化は100mあたり</text></svg>');
