  put('s_h1', 4, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="メスフラスコでは、溶質をとかしてから標線まで水を加え、溶液全体の体積を決める。モル濃度は溶質のmolを溶液全体の体積Lでわる。0.10molで全体0.200Lなら0.50mol/L"><rect x="44" y="14" width="14" height="50" class="bx"/><circle cx="51" cy="98" r="32" class="bx"/><circle cx="51" cy="98" r="31" class="fl"/><rect x="45" y="38" width="12" height="40" class="fl"/><line x1="40" y1="38" x2="62" y2="38" class="cv2"/><line x1="62" y1="38" x2="76" y2="30" class="ax"/><text x="78" y="32">標線</text><rect x="42" y="130" width="18" height="4" class="ax"/><text x="51" y="146" text-anchor="middle">メスフラスコ</text><text x="108" y="30">モル濃度[mol/L]</text><text x="108" y="46">= 溶質[mol]</text><text x="108" y="60">÷ 溶液の体積[L]</text><text x="108" y="82">分母は溶液全体</text><text x="108" y="96">(水の体積ではない)</text><text x="108" y="118">例:0.10mol を</text><text x="108" y="132">全体 0.200L にする</text><text x="108" y="146">→ 0.50mol/L</text></svg>');
  put('s_h1', 9, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="質量の割合から組成式を決める。鉄70g・酸素30gを原子量でわるとmolは1.25と1.875で、比は2:3なので組成式はFe₂O₃"><text x="6" y="14">鉄の酸化物 100g(Fe=56, O=16)</text><text x="6" y="40">質量</text><rect x="40" y="28" width="119" height="18" class="tr"/><rect x="159" y="28" width="51" height="18" class="bx"/><text x="100" y="41" text-anchor="middle">Fe 70g</text><text x="184" y="41" text-anchor="middle">O 30g</text><text x="64" y="62">÷56</text><text x="170" y="62">÷16</text><text x="6" y="86">mol</text><rect x="40" y="74" width="68" height="18" class="tr"/><rect x="108" y="74" width="102" height="18" class="bx"/><text x="74" y="87" text-anchor="middle">1.25</text><text x="159" y="87" text-anchor="middle">1.875</text><text x="6" y="116">比</text><text x="74" y="116" text-anchor="middle">2</text><text x="108" y="116" text-anchor="middle">:</text><text x="159" y="116" text-anchor="middle">3</text><text x="110" y="140" text-anchor="middle">組成式 Fe₂O₃</text></svg>');
  put('s_acid', 1, 'fig', '<svg viewBox="0 0 220 156" class="lz-fig" role="img" aria-label="強酸の塩酸は水溶液中でほぼ全部がH⁺とCl⁻に電離する(電離度≒1)。弱酸の酢酸は大部分が分子のままで、一部だけが電離する"><path d="M8 30 L8 120 L104 120 L104 30" class="ax"/><rect x="9" y="40" width="94" height="79" class="fl"/><path d="M116 30 L116 120 L212 120 L212 30" class="ax"/><rect x="117" y="40" width="94" height="79" class="fl"/><text x="16" y="58">H⁺</text><text x="34" y="58">Cl⁻</text><text x="60" y="58">H⁺</text><text x="78" y="58">Cl⁻</text><text x="16" y="80">H⁺</text><text x="34" y="80">Cl⁻</text><text x="60" y="80">H⁺</text><text x="78" y="80">Cl⁻</text><text x="16" y="102">H⁺</text><text x="34" y="102">Cl⁻</text><text x="60" y="102">H⁺</text><text x="78" y="102">Cl⁻</text><text x="122" y="56">CH₃COOH</text><text x="122" y="74">CH₃COOH</text><text x="122" y="92">CH₃COOH</text><text x="122" y="112">H⁺ + CH₃COO⁻</text><text x="56" y="20" text-anchor="middle">塩酸 HCl</text><text x="164" y="20" text-anchor="middle">酢酸</text><text x="56" y="136" text-anchor="middle">強酸:ほぼ全部電離</text><text x="164" y="136" text-anchor="middle">弱酸:一部だけ電離</text><text x="56" y="150" text-anchor="middle">電離度≒1</text><text x="164" y="150" text-anchor="middle">電離度が小さい</text></svg>');
  put('s_acid', 9, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="逆滴定。硫酸が出すH⁺0.010molのうち、NaOHで滴定した残りの0.0030molを引くと、アンモニアが受けとったH⁺は0.0070molと分かる"><text x="6" y="16">硫酸が出す H⁺ 0.010mol</text><rect x="10" y="24" width="200" height="24" class="bx"/><text x="110" y="40" text-anchor="middle">H⁺ 0.010mol</text><rect x="10" y="70" width="140" height="24" class="tr"/><rect x="150" y="70" width="60" height="24" class="fl"/><text x="80" y="86" text-anchor="middle">NH₃ 0.0070mol</text><text x="180" y="86" text-anchor="middle">NaOH</text><line x1="10" y1="48" x2="10" y2="70" class="dash"/><line x1="150" y1="48" x2="150" y2="70" class="dash"/><line x1="210" y1="48" x2="210" y2="70" class="dash"/><text x="152" y="110">0.0030mol</text><text x="10" y="110">← 求めたい量</text><text x="6" y="132">NH₃ = 0.010 − 0.0030</text><text x="6" y="146">= 0.0070mol(残りから求める)</text></svg>');
