  put('s_life', 9, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="ペーパークロマトグラフィー。溶媒の先端が原点から6.0cm、しみAが1.5cm、Bが3.6cm進んだとき、Rf値はAが0.25、Bが0.60"><rect x="14" y="122" width="76" height="22" class="fl"/><rect x="30" y="14" width="44" height="122" class="bx"/><line x1="26" y1="120" x2="80" y2="120" class="dash"/><line x1="26" y1="30" x2="80" y2="30" class="dash"/><circle cx="52" cy="120" r="3" class="ax"/><circle cx="52" cy="97.5" r="5" class="tr"/><circle cx="52" cy="66" r="5" class="pt"/><text x="40" y="101.5" text-anchor="middle">A</text><text x="40" y="70" text-anchor="middle">B</text><line x1="92" y1="120" x2="92" y2="30" class="ax"/><path d="M93.9 33.5 L92 30 L90.1 33.5" class="ax"/><line x1="104" y1="120" x2="104" y2="66" class="cv2"/><path d="M105.9 69.5 L104 66 L102.1 69.5" class="cv2"/><line x1="116" y1="120" x2="116" y2="97.5" class="cv"/><path d="M117.9 101 L116 97.5 L114.1 101" class="cv"/><text x="84" y="24">6.0</text><text x="98" y="60">3.6</text><text x="110" y="92">1.5</text><text x="8" y="116">原点</text><text x="76" y="13">溶媒の先端</text><text x="140" y="40">Rf 値</text><text x="140" y="56">= 成分の距離</text><text x="140" y="70">÷ 溶媒の距離</text><text x="140" y="96">A 1.5÷6.0</text><text x="140" y="110">  = 0.25</text><text x="140" y="128">B 3.6÷6.0</text><text x="140" y="142">  = 0.60</text></svg>');
  put('sx_h', 4, 'fig', '<svg viewBox="0 0 220 144" class="lz-fig" role="img" aria-label="なめらかな坂を高さhから下りた物体は、坂が曲がっていても(実線)まっすぐでも(点線)、下で同じ速さv=√(2gh)になる。はじめの位置エネルギーmghがすべて運動エネルギーに変わる"><line x1="10" y1="130" x2="210" y2="130" class="ax"/><path d="M20 30 C60 30 60 128 120 128 L200 128" class="cv"/><path d="M20 30 L120 128" class="dash"/><circle cx="20" cy="24" r="6" class="tr"/><circle cx="170" cy="122" r="6" class="tr"/><line x1="178" y1="122" x2="204" y2="122" class="cv2"/><path d="M200.5 123.9 L204 122 L200.5 120.1" class="cv2"/><line x1="8" y1="128" x2="8" y2="32" class="ax"/><path d="M9.9 35.5 L8 32 L6.1 35.5" class="ax"/><text x="12" y="84">h</text><text x="32" y="18">はじめ:mgh + 0</text><text x="110" y="96">あと:0 + ½mv²</text><text x="110" y="110">v = √(2gh)</text><text x="110" y="40">道の形によらず</text><text x="110" y="54">同じ速さ</text><text x="110" y="68">(摩擦なし)</text></svg>');
  put('sx_h', 8, 'fig', '<svg viewBox="0 0 220 156" class="lz-fig" role="img" aria-label="F-xグラフの面積は仕事。力が一定なら長方形でW=Fx、ばねのように力がkxで一様にふえるなら三角形で½kx²になり、これが弾性エネルギー"><line x1="14" y1="120" x2="104" y2="120" class="ax"/><line x1="14" y1="120" x2="14" y2="24" class="ax"/><rect x="14" y="60" width="70" height="60" class="fl"/><line x1="14" y1="60" x2="94" y2="60" class="cv"/><text x="18" y="18">力 F</text><text x="104" y="134" text-anchor="end">x</text><text x="49" y="94" text-anchor="middle">W = Fx</text><text x="56" y="150" text-anchor="middle">力が一定:長方形</text><line x1="116" y1="120" x2="206" y2="120" class="ax"/><line x1="116" y1="120" x2="116" y2="24" class="ax"/><path d="M116 120 L186 50 L186 120 Z" class="fl"/><line x1="116" y1="120" x2="196" y2="40" class="cv"/><line x1="186" y1="50" x2="186" y2="120" class="dash"/><text x="120" y="18">力 kx</text><text x="206" y="134" text-anchor="end">x</text><text x="188" y="56">kx</text><text x="160" y="108" text-anchor="middle">½·x·kx</text><text x="162" y="150" text-anchor="middle">ばね:三角形 ½kx²</text></svg>');
  put('hd_sci', 0, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="一定量のAにBを加えていくときの生成物の量。ちょうど反応する量まではBが不足でBの量に比例し、そのあとはAが不足になって生成物は一定"><line x1="30" y1="130" x2="212" y2="130" class="ax"/><line x1="30" y1="130" x2="30" y2="14" class="ax"/><path d="M30 130 L115 28 L208.5 28" class="cv"/><line x1="115" y1="28" x2="115" y2="130" class="dash"/><circle cx="115" cy="28" r="3" class="pt"/><text x="34" y="14">生成物の量</text><text x="212" y="144" text-anchor="end">加えた B の量</text><text x="115" y="144" text-anchor="middle">ちょうど</text><text x="121" y="20">A がなくなった</text><text x="34" y="44">B が不足</text><text x="34" y="58">B で決まる</text><text x="122" y="92">A が不足</text><text x="122" y="106">→ A で決まり</text><text x="122" y="120">一定</text></svg>');
  put('hd_sci', 4, 'fig', '<svg viewBox="0 0 220 156" class="lz-fig" role="img" aria-label="直列と並列が混ざった回路。内側の3Ωと6Ωの並列を3×6÷(3+6)=2Ωにまとめ、それに1Ωを直列につないで全体は3Ω"><line x1="10" y1="40" x2="34" y2="40" class="ax"/><line x1="34" y1="24" x2="34" y2="56" class="ax"/><line x1="34" y1="24" x2="54" y2="24" class="ax"/><line x1="34" y1="56" x2="54" y2="56" class="ax"/><rect x="54" y="18" width="30" height="12" class="bx"/><rect x="54" y="50" width="30" height="12" class="bx"/><line x1="84" y1="24" x2="104" y2="24" class="ax"/><line x1="84" y1="56" x2="104" y2="56" class="ax"/><line x1="104" y1="24" x2="104" y2="56" class="ax"/><line x1="104" y1="40" x2="126" y2="40" class="ax"/><rect x="126" y="34" width="30" height="12" class="bx"/><line x1="156" y1="40" x2="200" y2="40" class="ax"/><text x="69" y="14" text-anchor="middle">3Ω</text><text x="69" y="76" text-anchor="middle">6Ω</text><text x="141" y="30" text-anchor="middle">1Ω</text><text x="4" y="98">① 並列 3×6÷(3+6) = 2Ω</text><line x1="10" y1="122" x2="30" y2="122" class="ax"/><rect x="30" y="116" width="30" height="12" class="bx"/><line x1="60" y1="122" x2="80" y2="122" class="ax"/><rect x="80" y="116" width="30" height="12" class="bx"/><line x1="110" y1="122" x2="124" y2="122" class="ax"/><text x="45" y="112" text-anchor="middle">2Ω</text><text x="95" y="112" text-anchor="middle">1Ω</text><text x="130" y="126">② 直列</text><text x="4" y="148">全体 2 + 1 = 3Ω(内側からまとめる)</text></svg>');
