  put('s_eco', 10, 'fig', '<svg viewBox="0 0 220 160" class="lz-fig" role="img" aria-label="物質収支の関係。生産者は総生産量=純生産量+呼吸量。消費者は摂食量=同化量+不消化排出量、同化量=生産量+呼吸量。エネルギー効率は同化量を1つ下の段階の同化量(生産者は総生産量)でわる"><text x="6" y="25">生産者</text><rect x="60" y="10" width="150" height="22" class="tr"/><text x="135" y="25" text-anchor="middle">総生産量</text><text x="6" y="49"></text><rect x="60" y="34" width="96" height="22" class="bx"/><text x="108" y="49" text-anchor="middle">純生産量</text><rect x="156" y="34" width="54" height="22" class="fl"/><text x="183" y="49" text-anchor="middle">呼吸量</text><text x="6" y="83">消費者</text><rect x="60" y="68" width="150" height="22" class="tr"/><text x="135" y="83" text-anchor="middle">摂食量</text><text x="6" y="107"></text><rect x="60" y="92" width="104" height="22" class="bx"/><text x="112" y="107" text-anchor="middle">同化量</text><rect x="164" y="92" width="46" height="22" class="fl"/><text x="187" y="107" text-anchor="middle">不消化</text><text x="6" y="131"></text><rect x="60" y="116" width="62" height="22" class="bx"/><text x="91" y="131" text-anchor="middle">生産量</text><rect x="122" y="116" width="42" height="22" class="fl"/><text x="143" y="131" text-anchor="middle">呼吸量</text><text x="6" y="152">効率 = 同化量÷1つ下の同化量×100</text></svg>');
  put('s_geo', 4, 'fig', '<svg viewBox="0 0 220 158" class="lz-fig" role="img" aria-label="地質年代。46億年のうち先カンブリア時代が約88%をしめる。最近の5.4億年は古生代(三葉虫)、中生代(アンモナイト・恐竜、2.5億年前から)、新生代(ビカリア・マンモス、6600万年前から)"><text x="6" y="14">46億年を1本にすると</text><rect x="10" y="22" width="176" height="20" class="bx"/><rect x="186" y="22" width="24" height="20" class="tr"/><text x="98" y="36" text-anchor="middle">先カンブリア時代(約88%)</text><text x="6" y="66">最近の5.4億年を拡大</text><rect x="10" y="72" width="107.4" height="22" class="tr"/><rect x="117.4" y="72" width="68.1" height="22" class="fl"/><rect x="185.6" y="72" width="24.4" height="22" class="bx"/><text x="63.7" y="87" text-anchor="middle">古生代</text><text x="151.5" y="87" text-anchor="middle">中生代</text><text x="197.8" y="87" text-anchor="middle">新</text><text x="6" y="106">5.4億</text><text x="117.4" y="106" text-anchor="middle">2.5億</text><text x="212" y="106" text-anchor="end">6600万年前</text><text x="6" y="124">古生代:三葉虫・魚類・両生類</text><text x="6" y="138">中生代:アンモナイト・恐竜</text><text x="6" y="152">新生代:ビカリア・マンモス・人類</text></svg>');
